import pandas as pd, numpy as np

df=pd.read_csv('/root/environment/data/ckd_lab_data.csv')

# quick parse similar to plan

def parse_value(v):
    if pd.isna(v):
        return np.nan
    s=str(v).strip()
    if s=='' or s.lower() in ('nan','none','null','na','n/a'):
        return np.nan
    if ',' in s and '.' in s:
        if s.rfind(',') < s.rfind('.'):
            s = s.replace(',', '')
        else:
            s = s.replace('.', '').replace(',', '.')
    elif ',' in s:
        s = s.replace(',', '.')
    try:
        return float(s)
    except:
        return np.nan

numeric_cols=[c for c in df.columns if c!='patient_id']
for col in numeric_cols:
    df[col]=df[col].map(parse_value)

print('rows', df.shape)
print('missing rows', df.isna().any(axis=1).sum())

# check WBC, Platelet, RBC ranges
ranges={'WBC_Count':(0.5,50.0),'Platelet_Count':(10.0,1500.0),'RBC_Count':(1.5,7.0)}
for col,(mn,mx) in ranges.items():
    vals=df[col].dropna()
    out=vals[(vals<mn)|(vals>mx)]
    print(col, 'out', len(out),'min',vals.min(),'max',vals.max(),'out-min', out.min() if len(out) else None,'out-max',out.max() if len(out) else None)
